function stockProblem(items,exceptOrderId=""){const totals=new Map();for(const item of items)totals.set(item.id,(totals.get(item.id)||0)+(Number(item.quantity)||0));for(const[id,quantity]of totals){const state=productStockState(id,exceptOrderId);if(state.tracked&&quantity>state.available){const product=catalog.items.find(item=>item.id===id);return`${product?.name||'Bağlı ürün'} stoğunda en fazla ${state.available} adet var.`}}return""}
