function openCreditOrder(){const o=orderFor(selectedKey),customer=linkedCreditCustomer();if(!o||!customer)return;el.creditOrderCustomer.textContent=customer.name;el.creditExistingDebt.textContent=money(customer.balance||0);el.creditAvailableBalance.textContent=money(customer.creditBalance||0);el.creditOrderTotal.textContent=money(orderTotal(o));el.creditOrderForm.elements.creditPaymentType.value='cash';el.creditCashInput.value=0;renderCreditPreview();if(!el.creditOrderDialog.open)el.creditOrderDialog.showModal();setTimeout(()=>el.creditCashInput.select(),50)}
