async function saveCreditOrder(e){
  e.preventDefault();
  if(busy)return;
  const o=orderFor(selectedKey),customer=linkedCreditCustomer();
  if(!o||!customer){show('Masaya bağlı Açık Hesap müşterisi bulunamadı.');return}
  const requestedPayment=Math.max(0,Number(String(el.creditCashInput.value).replace(',','.'))||0);
  const paymentType=el.creditOrderForm.elements.creditPaymentType.value;
  busy=true;
  try{
    let finalDebt=0,finalCredit=0,creditUsed=0;
    await runTransaction(db,async tx=>{
      const orderRef=doc(ordersCol,o.id),customerRef=doc(creditCol,customer.id);
      const orderSnap=await tx.get(orderRef),customerSnap=await tx.get(customerRef);
      if(!orderSnap.exists()||!customerSnap.exists())throw new Error('missing');
      const fresh={id:orderSnap.id,...orderSnap.data()},customerData=customerSnap.data();
      const fullTotal=billTotal(fresh),previousPaid=orderPaid(fresh),orderRemaining=Math.max(0,fullTotal-previousPaid);
      const existingDebt=Math.max(0,Number(customerData.balance)||0),availableCredit=Math.max(0,Number(customerData.creditBalance)||0);
      const currentOrderPaid=Math.min(requestedPayment,orderRemaining),afterOrderPayment=Math.max(0,requestedPayment-currentOrderPaid),openAccountPaid=Math.min(afterOrderPayment,existingDebt),creditAddedFromPayment=Math.max(0,afterOrderPayment-openAccountPaid);
      const net=availableCredit+requestedPayment-existingDebt-orderRemaining;
      finalDebt=Math.max(0,-net);finalCredit=Math.max(0,net);
      creditUsed=Math.min(availableCredit,existingDebt+orderRemaining);
      const saleRef=doc(salesCol),deductions=[];
      for(const stock of stocks.filter(s=>s.active!==false&&s.automaticDeduction&&s.linkedMenuItemId)){
        const qty=fresh.items.filter(i=>i.id===stock.linkedMenuItemId).reduce((n,i)=>n+i.quantity,0)*(Number(stock.deductionAmount)||1);
        if(qty>0){const ref=doc(stockCol,stock.id),snap=await tx.get(ref);deductions.push({ref,snap,stock,qty})}
      }
      tx.update(customerRef,{balance:finalDebt,creditBalance:finalCredit,updatedAt:serverTimestamp()});
      tx.set(doc(creditMovesCol),{customerId:customer.id,customerName:customerData.name,type:'debt',amount:orderRemaining,creditUsed,previousBalance:existingDebt,resultingBalance:finalDebt,previousCreditBalance:availableCredit,resultingCreditBalance:finalCredit,operationDate:fresh.businessDate||businessDate,businessDate:fresh.businessDate||businessDate,note:`${fresh.title} Adisyon borcu`,source:'pos',saleId:saleRef.id,createdAt:serverTimestamp(),createdBy:auth.currentUser.uid});
      if(requestedPayment>0)tx.set(doc(creditMovesCol),{customerId:customer.id,customerName:customerData.name,type:paymentType==='transfer'?'transfer':'payment',amount:requestedPayment,orderPaid:currentOrderPaid,debtPaid:openAccountPaid,creditAdded:creditAddedFromPayment,previousBalance:existingDebt+orderRemaining,resultingBalance:finalDebt,previousCreditBalance:availableCredit,resultingCreditBalance:finalCredit,operationDate:fresh.businessDate||businessDate,businessDate:fresh.businessDate||businessDate,note:`${fresh.title} müşteri hesabı ödemesi`,source:'pos',saleId:saleRef.id,createdAt:serverTimestamp(),createdBy:auth.currentUser.uid});
      for(const d of deductions){
        const current=Number(d.snap.data()?.quantity)||0,next=current-d.qty;
        tx.update(d.ref,{quantity:next,updatedAt:serverTimestamp()});
        tx.set(doc(stockMovesCol),{stockItemId:d.stock.id,stockName:d.stock.name,type:'out',amount:d.qty,previousQuantity:current,resultingQuantity:next,unit:d.stock.unit,operationDate:fresh.businessDate||businessDate,note:`Adisyon ${fresh.title}`,source:'pos',saleId:saleRef.id,createdAt:serverTimestamp(),createdBy:auth.currentUser.uid});
      }
      tx.set(saleRef,{recordType:'sale',settlementType:'credit',orderId:fresh.id,title:fresh.title,slotKey:fresh.slotKey,customerId:customer.id,customerName:customerData.name,items:fresh.items,subtotal:fresh.items.reduce((s,i)=>s+i.unitPrice*i.quantity,0),complimentaryTotal:fresh.items.filter(i=>i.complimentary).reduce((s,i)=>s+i.unitPrice*i.quantity,0),baseTotal:fullTotal,paymentAmount:requestedPayment,cashAmount:paymentType==='cash'?requestedPayment:0,transferAmount:paymentType==='transfer'?requestedPayment:0,currentOrderPaid,openAccountPaid,creditAddedFromPayment,creditBalanceUsed:creditUsed,openAccountAmount:Math.max(0,finalDebt-existingDebt),tipAmount:0,paymentType,businessDate:fresh.businessDate||businessDate,closedAtMs:Date.now(),closedAt:serverTimestamp(),createdBy:auth.currentUser.uid,...markInstantCashMovement('credit',fresh.businessDate||businessDate)});bumpCashMovement(tx,{scope:'credit',account:paymentType==='transfer'?'bank':'cash',amount:requestedPayment,date:fresh.businessDate||businessDate});
      tx.delete(orderRef);
    });
    el.creditOrderDialog.close();showTables();
    show(finalDebt?`Adisyon kapandı. Müşterinin kalan borcu ${money(finalDebt)}.`:`Adisyon kapandı. Müşterinin Artı Bakiyesi ${money(finalCredit)}.`);
  }catch(error){console.error(error);show('Müşteri hesabı İşlemi tamamlanamadı.')}finally{busy=false}
}
